54:   function setText(){document.querySelector('[data-i18n="world"]').textContent=t('world');document.querySelector('[data-i18n="level"]').textContent=t('level');document.querySelector('[data-i18n="quest"]').textContent=t('quest');document.querySelector('[data-i18n="inventory"]').textContent=t('inventory');$('modalTitle').textContent=t('title');$('modalText').textContent=t('intro');$('resumeBtn').childNodes[0].textContent=t('go')+' ';$('questTitle').textContent=t('questTitle');$('questDesc').textContent=gemCount>=3?t('portal'):t('questDesc');document.querySelector('.map-coords span').textContent='● '+t('safe').toUpperCase();$('languageSelect').value=lang}
55:   function updateHud(){$('gemCount').textContent=gemCount;$('potionCount').textContent=potions;$('blockCount').textContent=blocks;$('essenceCount').textContent=essence;$('gemBoxCount').textContent=gemBoxes;$('healthFill').style.width=(player.hp/player.maxHp*100)+'%';$('healthText').textContent=Math.ceil(player.hp)+' / '+player.maxHp;$('questFill').style.width=Math.min(100,gemCount/3*100)+'%';$('questCount').textContent=`${Math.min(gemCount,3)} / 3 ${t('crystal')}`;$('questDesc').textContent=worldMode==='dungeon'?(dungeonCleared?dw('clear'):dw('blocked')):gemCount>=3?t('portal'):t('questDesc');$('xpFill').style.width=player.xp+'%';$('levelText').textContent=String(player.level).padStart(2,'0');$('className').textContent=classes[classIndex].name.toUpperCase();$('powerRank').textContent=powerRank}
56:   function openGemBox(){if(gemBoxes<1){toast('Sem Gem Box! Derrote guardioes ou conclua uma ruina.');return}gemBoxes--;gemTier++;powerRank+=3;player.maxHp+=5;player.hp=Math.min(player.maxHp,player.hp+5);toast(`Gem Box aberta! Gema de poder ${gemTier} · Poder ${powerRank}`);updateHud()}
