62:   function refreshClub(){const status=$('clubStatus');if(status)status.textContent=localClub?`Clube local: ${localClub.name} · nível ${localClub.level}/11 · ${localClub.xp}/100 XP · ${localClub.coins} moedas${localClub.primary?' · principal':''} · ${clubInvites.length} convite(s) simulado(s).`:'Sem clube criado neste dispositivo.';const fixtures=$('clubFixtures');if(fixtures)fixtures.textContent=localClub?`Shrine of Combat ${localClub.level>=11?'ATIVO (+15% dano)':'bloqueado · nível 11'} · Combat Crane ${localClub.level>=3?'disponível':'bloqueado · nível 3'} · Módulo Delve ${localClub.level>=5?'ativo (50% desconto simulado)':'bloqueado · nível 5'}`:'Fixtures demonstrativas desbloqueiam com níveis do clube local.';const crane=$('craneBtn');if(crane)crane.disabled=!localClub||localClub.level<3||localClub.coins<10||Date.now()<localClub.craneUntil}
