64:   function showModal(section='help'){paused=true;$('modalBackdrop').classList.remove('hidden');['help','settings','club'].forEach(name=>$(`${name}Content`).classList.toggle('hidden',name!==section));$('modalTitle').textContent=section==='settings'?'Configurações':section==='club'?'Clubes locais':t('title');$('modalText').textContent=section==='help'?t('intro'):section==='club'?'Gestão de clube em modo local de demonstração.':'Ajuste a apresentação para este dispositivo.';refreshClub()}
